        # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
        # No leading zeros in numeric parts or numeric prerelease identifiers
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'
        match = re.match(pattern, s)
        if not match:
            raise ValueError(f"Invalid version: {version_str}")

        self.major = int(match.group(1))
        self.minor = int(match.group(2))
        self.patch = int(match.group(3))
        prerelease_str = match.group(4)
        build_str = match.group(5)

        # Parse prerelease identifiers
        if prerelease_str:
            self.prerelease = tuple(prerelease_str.split('.'))
        else:
            self.prerelease = ()

        # Build metadata is stored but ignored for ordering
        self.build = build_str or ""

        # Validate prerelease identifiers: non-empty, [0-9A-Za-z-]+
        for ident in self.prerelease:
            if not ident or not re.match(r'^[0-9A-Za-z-]+$', ident):
                raise ValueError(f"Invalid prerelease identifier: {ident}")

        # Validate numeric prerelease identifiers: no leading zeros
        for ident in self.prerelease:
            if re.match(r'^\d+$', ident):
                if len(ident) > 1 and ident[0] == '0':
                    raise ValueError(f"Numeric prerelease identifier has leading zero: {ident}")

