        if not isinstance(other, Version):
            return NotImplemented
        # Compare major, minor, patch
        if (self.major, self.minor, self.patch) != (other.major, other.minor, other.patch):
            return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

        # Same version number: prerelease < release
        if not self.prerelease and other.prerelease:
            return False
        if self.prerelease and not other.prerelease:
            return True
        if not self.prerelease and not other.prerelease:
            return False

        # Compare prerelease identifiers
        for a, b in zip(self.prerelease, other.prerelease):
            # Numeric vs alphanumeric
            a_numeric = re.match(r'^\d+$', a) is not None
            b_numeric = re.match(r'^\d+$', b) is not None

            if a_numeric and b_numeric:
                # Compare numerically
                if int(a) != int(b):
                    return int(a) < int(b)
            elif a_numeric and not b_numeric:
                # Numeric < alphanumeric
                return True
            elif not a_numeric and b_numeric:
                # Alphanumeric > numeric
                return False
            else:
                # Compare lexicographically (ASCII order)
                if a != b:
                    return a < b

        # If all compared identifiers are equal, shorter list is smaller
        return len(self.prerelease) < len(other.prerelease)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, self.prerelease))


