import dataclasses
from dataclasses import Field, MISSING
from typing import get_type_hints, Union, Optional, Literal, get_args, get_origin
import collections.abc


class LoadError(ValueError):
    def __init__(self, path, message):
        self.path = path
        super().__init__(f"{path}: {message}")


def load(cls, data):
    """Load a dataclass instance from JSON-like data."""
    return _load_value(cls, data, "$")


def _load_value(cls, data, path):
    """Load a value of type cls from data, with error path tracking."""
    # Handle None
    if cls is type(None):
        if data is not None:
            raise LoadError(path, f"expected None, got {type(data).__name__}")
        return None

    # Handle Literal
    origin = get_origin(cls)
    if origin is Literal:
        args = get_args(cls)
        if data not in args:
            raise LoadError(path, f"value {data!r} not in {args}")
        # Check type compatibility
        for arg in args:
            if type(data) is type(arg) and data == arg:
                return data
        raise LoadError(path, f"value {data!r} does not match any literal value type")

    # Handle Union types (including T | None)
    if origin is Union:
        args = get_args(cls)
        # Try each type in order
        last_error = None
        for arg in args:
            try:
                return _load_value(arg, data, path)
            except LoadError as e:
                last_error = e
        # If all failed, raise the last error (which might be from a nested type)
        raise last_error

    # Handle dataclasses
    if dataclasses.is_dataclass(cls):
        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict, got {type(data).__name__}")

        # Get field annotations and defaults
        try:
            hints = get_type_hints(cls)
        except Exception:
            # Fallback if get_type_hints fails (e.g., forward references that can't be resolved)
            hints = {f.name: f.type for f in dataclasses.fields(cls)}

        # Get field metadata
        fields = dataclasses.fields(cls)
        field_map = {f.name: f for f in fields}

        result = {}
        used_keys = set()

        # Process each field
        for field in fields:
            field_name = field.name
            field_path = f"{path}.{field_name}"

            if field_name not in data:
                # Missing key
                if field.default is not MISSING:
                    result[field_name] = field.default
                elif field.default_factory is not MISSING and field.default_factory is not None:
                    result[field_name] = field.default_factory()
                else:
                    raise LoadError(field_path, "missing required field")
                continue

            used_keys.add(field_name)
            field_data = data[field_name]
            field_type = hints.get(field_name, field.type)

            try:
                result[field_name] = _load_value(field_type, field_data, field_path)
            except LoadError as e:
                # Re-raise with updated path if needed
                raise LoadError(field_path, str(e).split(": ", 1)[1]) from e

        # Check for unknown keys
        for key in data:
            if key not in used_keys:
                raise LoadError(f"{path}.{key}", "unknown field")

        # Create instance
        try:
            return cls(**result)
        except TypeError as e:
            raise LoadError(path, f"failed to instantiate: {e}") from e

    # Handle list[T]
    if origin is list:
        args = get_args(cls)
        if not args:
            if not isinstance(data, list):
                raise LoadError(path, f"expected list, got {type(data).__name__}")
            return data

        item_type = args[0]
        if not isinstance(data, list):
            raise LoadError(path, f"expected list, got {type(data).__name__}")

        result = []
        for i, item in enumerate(data):
            item_path = f"{path}[{i}]"
            try:
                result.append(_load_value(item_type, item, item_path))
            except LoadError as e:
                raise LoadError(item_path, str(e).split(": ", 1)[1]) from e
        return result

    # Handle dict[str, T]
    if origin is dict:
        args = get_args(cls)
        if not args:
            if not isinstance(data, dict):
                raise LoadError(path, f"expected dict, got {type(data).__name__}")
            return data

        key_type, value_type = args
        if key_type is not str:
            # Only support dict[str, T]
            raise LoadError(path, "only dict[str, T] is supported")

        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict, got {type(data).__name__}")

        result = {}
        for k, v in data.items():
            if not isinstance(k, str):
                raise LoadError(path, f"dict keys must be strings, got {type(k).__name__}")
            item_path = f"{path}.{k}"
            try:
                result[k] = _load_value(value_type, v, item_path)
            except LoadError as e:
                raise LoadError(item_path, str(e).split(": ", 1)[1]) from e
        return result

    # Handle tuple[T, ...] (variable-length tuple)
    if origin is tuple:
        args = get_args(cls)
        if not args:
            if not isinstance(data, list):
                raise LoadError(path, f"expected list, got {type(data).__name__}")
            return data

        # Check if it's a fixed-length tuple (e.g., tuple[int, str])
        if len(args) == 2 and args[1] is Ellipsis:
            # Variable-length tuple: tuple[T, ...]
            item_type = args[0]
            if not isinstance(data, list):
                raise LoadError(path, f"expected list, got {type(data).__name__}")

            result = []
            for i, item in enumerate(data):
                item_path = f"{path}[{i}]"
                try:
                    result.append(_load_value(item_type, item, item_path))
                except LoadError as e:
                    raise LoadError(item_path, str(e).split(": ", 1)[1]) from e
            return tuple(result)
        else:
            # Fixed-length tuple: tuple[A, B, C]
            if not isinstance(data, list):
                raise LoadError(path, f"expected list, got {type(data).__name__}")
            if len(data) != len(args):
                raise LoadError(path, f"expected list of length {len(args)}, got {len(data)}")

            result = []
            for i, (item, item_type) in enumerate(zip(data, args)):
                item_path = f"{path}[{i}]"
                try:
                    result.append(_load_value(item_type, item, item_path))
                except LoadError as e:
                    raise LoadError(item_path, str(e).split(": ", 1)[1]) from e
            return tuple(result)

    # Handle basic types
    # bool must not be accepted for int or float
    if cls is int:
        if isinstance(data, bool) or not isinstance(data, int):
            raise LoadError(path, f"expected int, got {type(data).__name__}")
        return data

    if cls is float:
        if isinstance(data, bool):
            raise LoadError(path, f"expected float, got bool")
        if isinstance(data, int):
            return float(data)
        if not isinstance(data, float):
            raise LoadError(path, f"expected float, got {type(data).__name__}")
        return data

    if cls is str:
        if not isinstance(data, str):
            raise LoadError(path, f"expected str, got {type(data).__name__}")
        return data

    if cls is bool:
        if not isinstance(data, bool):
            raise LoadError(path, f"expected bool, got {type(data).__name__}")
        return data

    # If we get here, it's an unsupported type
    raise LoadError(path, f"unsupported type {cls}")
